        unit: '48px',
        src: require('@/assets/images/ico_filter_stroke3.png'),
        toucharea: 3,
      },
    ],
    imgRatio: [
      { named: 'one-1', ratioSize: '1:1' },
      { named: 'two-3', ratioSize: '2:3' },
      { named: 'three-4', ratioSize: '3:4' },
      { named: 'four-3', ratioSize: '4:3' },
      { named: 'three-2', ratioSize: '3:2' },
      { named: 'sixteen-9', ratioSize: '16:9' },
    ],
    primary: [
      '#9E9E9E grey darken-1', 
      '#757575 grey darken-2', 
      '#616161 grey darken-3', 
      '#424242 grey darken-4',
      '#333333 grey darken-5',
    ],
    sub: [
      '#FFFF00 yellow accent1', 
      '#FFEA00 yellow accent2',
      '#FFD600 yellow accent3',
      '#FFAB00 amber accent1',
      '#FF8500 amber accent2',
    ],
  }),
  mounted() {
    this.guideColor()
    this.receiveStatus()
    this.getMode()
    this.onScroll()
    
    document.addEventListener('load', this.getMode, true)
    window.addEventListener("scroll", this.onScroll, true)
  },
  beforeUnmount() {
    document.removeEventListener('click', this.guideColor, true)
    document.removeEventListener('click', this.receiveStatus, true)
    document.removeEventListener('load', this.getMode, true)
    window.removeEventListener("scroll", this.onScroll, true)
  },
  methods: {
    guideColor(){
      const palette = document.querySelectorAll('.palette');
      // console.log(sortingConts);
      
      for(let idx = 0; idx < palette.length; idx++) {
        palette[idx].addEventListener('click', () => {
          palette[idx].classList.add('isActive');
          for(let idx_dif = 0; idx_dif < palette.length; idx_dif++) {
            /* 인덱스가 서로 다르면 isActive 클레스 제거 */  
            if(idx !== idx_dif) {
              palette[idx_dif].classList.remove('isActive');
            }
          }
        })
      }
    },
    getMode() {
      let thisPage = document.querySelector('#app'),
          modeStatus = document.querySelector('.toggle_luminosity');

      if(thisPage.classList.contains('dark-mode') === true) {
        // console.log('thisPage 다크 모드??:' + thisPage.classList.contains('dark-mode'))
        modeStatus.classList.remove('light')
        modeStatus.classList.add('dark')
      }
    },
    receiveStatus() {
      let detector = document.querySelector('.toggle_luminosity');

      detector.addEventListener('click', (e) => {
        let app = document.querySelector('#app');

        // console.log(modeLight, modeDark)
        console.log(e.currentTarget)
          if(e.currentTarget.classList.contains('light') === true) {
            console.log('라이트 모드 감지')
            app.classList.add('dark-mode')
            detector.classList.add('dark')
            detector.classList.remove('light')
          } 
          else if(e.currentTarget.classList.contains('dark') === true) {
            console.log('다크 모드 감지')
            app.classList.remove('dark-mode')
            detector.classList.remove('dark')
            detector.classList.add('light')
          }
      }, true)
    },
    onScroll() {
      // console.log('scrolled');
      // this.windowTop = e.target.scrollTop;

      const header = document.querySelector('.header');
      
      this.windowTop = window.top.scrollY;
      console.log(this.windowTop);

      if(this.windowTop >= this.header.height) {
        header.classList.add('scrolled');
      } else {
        header.classList.remove('scrolled');
      }
    }
  }
}
