<template>
  <HeaderEl
    @change-theme="receiveStatus"
    @load="getMode"
    class="header"
    :name="sceneName">
  </HeaderEl>

  <!-- 본문 -->
  <main class="wrap" @onScroll="onScroll" id="main">
    <h2 class="mgt8">컴포넌트 모음</h2>
    <dl class="sortComponent">
      <dt><abbr title="Insert">I</abbr></dt>
      <dd>:&nbsp;Insert&nbsp;[ 컴포넌트 적용 ]&nbsp;,</dd>
      <dt><abbr title="Named">N</abbr></dt>
      <dd>:&nbsp;Named&nbsp;[ 컴포넌트 선언 ]</dd>
    </dl>
    <ol class="sortUi">
      <li class="adopt_heightLv1">
        <h3>1. 아이콘 웹 폰트</h3>
        <CodeIcofont></CodeIcofont>
      </li>
      <li>
        <h3>2. 헤더</h3>
        <div class="affected_scroll">
          <CodeHeader
            @reset-subtitle="receiveLoad"></CodeHeader>
        </div>
      </li>
      <li>
        <h3>3. 바텁 탭메뉴</h3>
        <div class="adopt_heightLvMin get_bottomTab">
          <!-- <CodeNavbar
            @reset-subtab="receiveLoad2"></CodeNavbar> -->
            <CodeNavbar></CodeNavbar>
        </div>
      </li>
      <li>
        <h3>4. 테이블</h3>
        <div class="adopt_heightLvMin">
          <CodeTable></CodeTable>
        </div>
      </li>

      <!-- color UI (UI 모음으로 이전) 
          화면[asIs -> toBe] 
          UI 가이드 -> UI 모음
          컴포넌트 -> 코드 rule
            컴포넌트
            스타일링(Scss)
            폴더링
      -->
      <!-- transition(슬라이드 업/다운) UI -->
    </ol>
    <section class="uiGuide">
    </section>
  </main>
</template>

<script>
import HeaderEl from './common/Header.vue';
import CodeIcofont from './common/CodeIcofont.vue';
import CodeNavbar from './common/CodeNavbar.vue';
import CodeHeader from './common/CodeHeader.vue';
import CodeTable from './common/CodeTable.vue';

export default {
  // el: '#test',
  name: 'UiCompo',
  components: {
    HeaderEl,
    CodeHeader,
    CodeNavbar,
    CodeIcofont,
    CodeTable,
  },
  data: () => ({
    sceneName: '컴포넌트',
    header: {
      height: 60,
    },
  }),
  mounted() {
    this.receiveStatus()
    this.getMode()
    this.onScroll()
    this.receiveLoad()
    // this.receiveLoad2()

    document.addEventListener('load', this.getMode, true)
    window.addEventListener('scroll', this.onScroll, true)
  },
  beforeUnmount() {
    document.removeEventListener('click', this.receiveStatus, true)
    document.removeEventListener('load', this.getMode, true)
    window.removeEventListener('scroll', this.onScroll, true)
  },
  methods: {
    getMode() {
      let thisPage = document.querySelector('#app'),
          modeStatus = document.querySelector('.toggle_luminosity');

      if(thisPage.classList.contains('dark-mode') === true) {
        // console.log('thisPage 다크 모드??:' + thisPage.classList.contains('dark-mode'))
        modeStatus.classList.remove('light')
        modeStatus.classList.add('dark')
      }
    },
    receiveStatus() {
      let detector = document.querySelector('.toggle_luminosity');

      detector.addEventListener('click', (e) => {
        let app = document.querySelector('#app');

        // console.log(modeLight, modeDark)
        console.log(e.currentTarget)
          if(e.currentTarget.classList.contains('light') === true) {
            console.log('라이트 모드 감지')
            app.classList.add('dark-mode')
            detector.classList.add('dark')
            detector.classList.remove('light')
          } 
          else if(e.currentTarget.classList.contains('dark') === true) {
            console.log('다크 모드 감지')
            app.classList.remove('dark-mode')
            detector.classList.remove('dark')
            detector.classList.add('light')
          }
      }, true)
    },
    receiveLoad() {        
      // let subHeader = document.querySelector('.affected_scroll .header'),
      let subTitle = document.querySelector('.affected_scroll h1'),
          toggleBtn = document.querySelector('.affected_scroll .toggle_luminosity');

      subTitle.remove()
      toggleBtn.remove()
      // subHeader.append = '<p>헤더 요소</p>';
    },
    /*receiveLoad2() {        
      let subTab = document.querySelector('.get_bottomTab h2'),
          tabBar = document.querySelector('.get_bottomTab .bottom_tab');

      subTab.remove()
      tabBar.classList.remove('backdrop-filter');

      // subHeader.append = '<p>헤더 요소</p>';
    },*/
    onScroll() {
      // console.log('scrolled');
      // this.windowTop = e.target.scrollTop;

      const header = document.querySelector('.header');
      
      this.windowTop = window.top.scrollY;
      console.log(this.windowTop);

      if(this.windowTop >= this.header.height) {
        header.classList.add('scrolled');
      } else {
        header.classList.remove('scrolled');
      }
    }
  }
}
</script>

